"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[839],{80839:t=>{t.exports=JSON.parse('{"slug":"dorozhnye-stroiteli-prosrochka-kredity-oktyabr-2026","locale":"ru","title":"Просрочка крупных дорожных строителей по кредитам с марта выросла вдвое, почти до 9 млрд рублей","description":"Просрочка крупных дорожных строителей по кредитам выросла вдвое, почти до 9 млрд рублей. Как сокращение заказов и кассовый разрыв бьют по подрядчикам.","blocks":[{"id":"b001","kind":"paragraph","text":"Национальная ассоциация инфраструктурных компаний посчитала долги 22 крупных строителей дорог и мостов, среди них \xabДСК Автобан\xbb, \xabНацпроектстрой\xbb и \xabДороги и мосты\xbb. К концу августа их просрочка по кредитам выросла по сравнению с мартом больше чем вдвое, почти до 9 млрд рублей. Растут и сами долги: по кредитам на 11,8%, до 191 млрд рублей, перед поставщиками и подрядчиками на 16%, до 495 млрд. Две компании из выборки уже в процедуре банкротства."},{"id":"b002","kind":"paragraph","text":"Дороги заказывает в основном государство, и заказов стало меньше. За январь–сентябрь регионы потратили на строительство инфраструктуры около 1 трлн рублей, на 19,1% меньше, чем годом раньше. Федеральные нацпроекты \xabИнфраструктура для жизни\xbb и \xabЭффективная транспортная система\xbb получили 886,8 млрд, на 3,1% больше, но падение в регионах это не перекрыло. Заказчики в одностороннем порядке расторгли с членами ассоциации 18 контрактов на 80,5 млрд рублей."},{"id":"b003","kind":"paragraph","text":"Представим мастера, который ремонтирует квартиру. Плитку, краску и зарплату помощнику он оплачивает сразу, а хозяин рассчитается после приёмки. Если хозяин тянет с оплатой, мастер покупает материалы для следующего заказа с кредитной карты. Чем дольше задержка, тем больше процентов он отдаёт банку из своей прибыли. Это называют кассовым разрывом. Дорожные подрядчики закрывают его кредитами при ключевой ставке 14%, а сами заимствования, по словам Павла Якимчука из CMWP, обходятся им заметно дороже."},{"id":"b004","kind":"paragraph","text":"Банки видят этот риск и всё чаще отказывают компаниям отрасли, даже с чистой кредитной историей. Опасна и потеря банковской гарантии: без неё подрядчику приходится замораживать в обеспечение госконтракта собственные деньги или не участвовать в новых торгах. Гендиректор ассоциации Мария Ярмальчук называет это цепной реакцией. Заказчик расторгает контракт, банк видит риск и отказывает уже другим. В апреле ассоциация предупреждала о волне банкротств в течение 1–2 лет, и, по её оценке, за полгода прогноз начал сбываться."},{"id":"b005","kind":"paragraph","text":"За стройкой стоит бюджет. Дефицит федерального бюджета за 9 месяцев составил 5,2 трлн рублей, а план на год повышен до 7,3 трлн. Регионы тоже сокращают расходы, и первыми под нож идут стройки и ремонты: зарплаты бюджетников и социальные выплаты урезать сложнее. Рост расходов на инфраструктурные нацпроекты, запланированный на 2027 год, перенесён на 2028-й. Объём строительных работ в стране за январь–август снизился на 2,9%."},{"id":"b006","kind":"paragraph","text":"Для жителей регионов это означает, что ремонт и строительство дорог могут затянуться, а для работников отрасли растёт риск задержек зарплаты и сокращений. Якимчук ждёт, что просрочка продолжит расти ближайшие 6–9 месяцев. Если рост расходов в 2028 году состоится, выжившие подрядчики получат работу. Но чем дольше продлится разрыв до этого срока, тем меньше компаний до него доживёт, и рынок дорожного строительства станет концентрированнее."},{"id":"b007","kind":"heading","text":"Почему у дорожных строителей растут долги перед банками?"},{"id":"b008","kind":"paragraph","text":"Регионы за 9 месяцев 2026 года сократили расходы на строительство инфраструктуры на 19,1%, заказчики расторгли 18 контрактов на 80,5 млрд рублей, а оплата по действующим контрактам приходит с задержкой. Подрядчики закрывают разрывы кредитами, а при ставке 14% и выше обслуживать их всё труднее."},{"id":"b009","kind":"heading","text":"Что такое кассовый разрыв?"},{"id":"b010","kind":"paragraph","text":"Это ситуация, когда платить по счетам нужно сейчас, а деньги за сделанную работу придут позже. Компания может быть прибыльной на бумаге и всё равно не иметь денег на зарплаты и материалы. Разрыв закрывают кредитом, и его проценты уменьшают прибыль."},{"id":"b011","kind":"heading","text":"Чем кризис дорожных строителей грозит обычным людям?"},{"id":"b012","kind":"paragraph","text":"Ремонт и строительство дорог в регионах могут затянуться, а в отрасли под угрозой рабочие места. Рост расходов на инфраструктурные нацпроекты, запланированный на 2027 год, перенесён на 2028 год."}],"sources":[{"label":"Дорожные строители увязли в долгах","url":"https://www.kommersant.ru/doc/9044152"},{"label":"Просрочка инфраструктурных строителей выросла вдвое","url":"https://www.kommersant.ru/doc/9044417"},{"label":"Погрязли в долгах","url":"https://lenta.ru/news/2026/10/22/pogryazli-v-dolgah"},{"label":"Дефицит бюджета РФ уменьшился до 5,2 трлн рублей","url":"https://ru.themoscowtimes.com/2026/10/09/defitsit-byudzheta-rf-umenshilsya-do-52-trln-r-22-vvp-a208256"},{"label":"Две трети регионов урежут расходы на строительство и благоустройство","url":"https://ru.themoscowtimes.com/2026/10/03/dve-treti-rossiiskih-regionov-urezhut-rashodi-na-stroitelstvo-i-blagoustroistvo-iz-za-defitsita-byudzheta-a207702"}],"sourceBodySha256":"6a480ee0961bbb53dd585c0158613bf1c2f51eef98dcb29ae725c420947d9032"}')}}]);